:root {
  --bg: #fafaf7;
  --surface: #ffffff;
  --muted: #f1efe9;
  --ink: #15171a;
  --ink-soft: #4a4f57;
  --ink-mute: #6b7079;
  --line: #e5e2da;
  --accent: #c2410c;
  --accent-soft: #fde8d6;
  --focus: #1d4ed8;
  --radius: 14px;
  --radius-sm: 8px;
  --shadow-sm: 0 1px 2px rgba(20, 22, 26, 0.04);
  --shadow-md: 0 8px 24px rgba(20, 22, 26, 0.08);
  --container: 1200px;
  --space: clamp(1rem, 2vw, 1.5rem);
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Inter, "Helvetica Neue", Arial, sans-serif;
  font-size: 16px;
  line-height: 1.55;
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img, svg { display: block; max-width: 100%; }

h1, h2, h3 {
  font-family: ui-serif, "Iowan Old Style", "Georgia", "Times New Roman", serif;
  letter-spacing: -0.02em;
  line-height: 1.15;
  margin: 0 0 0.5rem;
  color: var(--ink);
}

h1 { font-size: clamp(2.25rem, 5vw, 3.75rem); }
h2 { font-size: clamp(1.65rem, 3vw, 2.25rem); }
h3 { font-size: 1.125rem; }

p { margin: 0 0 1rem; color: var(--ink-soft); }

a {
  color: var(--ink);
  text-decoration: none;
}
a:hover { text-decoration: underline; text-underline-offset: 3px; }

ul { list-style: none; padding: 0; margin: 0; }

button { font: inherit; cursor: pointer; }

/* Accessibility */
.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0);
  white-space: nowrap; border: 0;
}

.skip-link {
  position: absolute;
  left: 1rem; top: -3rem;
  background: var(--ink);
  color: #fff;
  padding: 0.6rem 1rem;
  border-radius: var(--radius-sm);
  z-index: 100;
  transition: top 0.2s ease;
}
.skip-link:focus { top: 1rem; outline: 2px solid var(--focus); outline-offset: 2px; }

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 3px;
  border-radius: 4px;
}

/* Layout */
.container {
  width: 100%;
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 var(--space);
}

/* Header */
.site-header {
  position: sticky;
  top: 0;
  background: rgba(250, 250, 247, 0.85);
  backdrop-filter: saturate(150%) blur(10px);
  border-bottom: 1px solid var(--line);
  z-index: 50;
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  padding-block: 0.85rem;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-weight: 700;
  font-size: 1.125rem;
  letter-spacing: -0.01em;
}
.brand:hover { text-decoration: none; }
.brand-mark {
  display: inline-grid;
  place-items: center;
  width: 28px; height: 28px;
  background: var(--ink);
  color: #fff;
  border-radius: 50%;
  font-size: 0.95rem;
}

.primary-nav ul {
  display: flex;
  gap: 1.75rem;
}
.primary-nav a {
  color: var(--ink-soft);
  font-size: 0.95rem;
  font-weight: 500;
}
.primary-nav a:hover { color: var(--ink); }

.header-actions {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
}
.icon-btn {
  position: relative;
  width: 40px; height: 40px;
  display: inline-grid;
  place-items: center;
  background: transparent;
  border: 0;
  border-radius: 50%;
  color: var(--ink);
  transition: background 0.15s;
}
.icon-btn:hover { background: var(--muted); }
.cart-count {
  position: absolute;
  top: 4px; right: 2px;
  min-width: 18px; height: 18px;
  background: var(--accent);
  color: #fff;
  font-size: 0.7rem;
  font-weight: 600;
  border-radius: 999px;
  display: grid; place-items: center;
  padding: 0 5px;
}

/* Hero */
.hero {
  padding: clamp(2rem, 6vw, 5rem) 0 clamp(2.5rem, 6vw, 5rem);
}
.hero-inner {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: clamp(2rem, 5vw, 4rem);
  align-items: center;
}
.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--accent);
  margin: 0 0 0.75rem;
}
.lede {
  font-size: 1.125rem;
  color: var(--ink-soft);
