  margin-block: 1rem 1.75rem;
}
.hero-cta {
  display: flex; flex-wrap: wrap; gap: 0.75rem;
  margin-bottom: 2rem;
}
.hero-meta {
  display: flex; flex-wrap: wrap; gap: 1.25rem 1.75rem;
  color: var(--ink-mute);
  font-size: 0.875rem;
}
.hero-meta li {
  position: relative;
  padding-left: 1.25rem;
}
.hero-meta li::before {
  content: "";
  position: absolute;
  left: 0; top: 0.55em;
  width: 6px; height: 6px;
  background: var(--accent);
  border-radius: 50%;
}

.hero-art {
  position: relative;
  aspect-ratio: 4/4.2;
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 0.85rem;
}
.hero-card {
  border-radius: var(--radius);
  background: var(--muted);
  box-shadow: var(--shadow-sm);
  position: relative;
  overflow: hidden;
}
.hero-card::after {
  content: "";
  position: absolute; inset: 0;
  background: radial-gradient(120% 80% at 30% 20%, rgba(255,255,255,0.45), transparent 60%);
}
.hero-card-1 {
  grid-row: span 2;
  background: linear-gradient(160deg, #d8c2a8, #b08a64);
}
.hero-card-2 { background: linear-gradient(140deg, #2c3037, #15171a); }
.hero-card-3 { background: linear-gradient(140deg, #f3d6b9, #e6a373); }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center; justify-content: center;
  padding: 0.85rem 1.4rem;
  border-radius: 999px;
  font-weight: 600;
  font-size: 0.95rem;
  border: 1.5px solid transparent;
  transition: transform 0.15s ease, background 0.15s, color 0.15s, border-color 0.15s;
