}
.category-grid a:hover { background: var(--muted); text-decoration: none; }
.cat-thumb {
  width: 64px; height: 64px;
  border-radius: 50%;
  background: var(--muted);
}
.cat-1 { background: linear-gradient(135deg, #d8c2a8, #b08a64); }
.cat-2 { background: linear-gradient(135deg, #c8d3c5, #6f8b75); }
.cat-3 { background: linear-gradient(135deg, #f3d6b9, #d68a4e); }
.cat-4 { background: linear-gradient(135deg, #c4ccd6, #5b6776); }
.cat-5 { background: linear-gradient(135deg, #b9c8a8, #4f6647); }
