}

/* Products */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.5rem;
}
.product {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex; flex-direction: column;
  transition: transform 0.18s ease, box-shadow 0.18s ease;
}
.product:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }
.product-media {
  aspect-ratio: 4/5;
  position: relative;
  overflow: hidden;
}
.product-media::after {
  content: "";
  position: absolute; inset: 0;
  background: radial-gradient(120% 80% at 30% 20%, rgba(255,255,255,0.5), transparent 65%);
  pointer-events: none;
}
.product-badge {
  position: absolute;
  top: 0.75rem; left: 0.75rem;
  background: var(--ink);
  color: #fff;
  font-size: 0.72rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 0.3rem 0.55rem;
  border-radius: 999px;
  z-index: 2;
}
.product-badge.sale { background: var(--accent); }
.product-body {
  padding: 1rem 1.1rem 1.2rem;
  display: flex; flex-direction: column;
  gap: 0.35rem;
  flex: 1;
}
.product-cat {
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--ink-mute);
  margin: 0;
}
.product-name {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  margin: 0;
  letter-spacing: -0.005em;
}
.product-meta {
  display: flex; align-items: center;
  justify-content: space-between;
  margin-top: auto;
  padding-top: 0.75rem;
  gap: 0.5rem;
}
.product-price {
  font-weight: 600;
  font-size: 1rem;
}
.product-price s {
  color: var(--ink-mute);
  font-weight: 400;
  margin-right: 0.4rem;
}
.add-btn {
  border: 1px solid var(--ink);
  background: transparent;
  color: var(--ink);
  padding: 0.45rem 0.85rem;
  border-radius: 999px;
  font-size: 0.82rem;
  font-weight: 600;
  transition: background 0.15s, color 0.15s;
}
.add-btn:hover { background: var(--ink); color: #fff; }
.add-btn.added { background: var(--accent); border-color: var(--accent); color: #fff; }

/* Deals */
.countdown {
  margin: 0;
  font-size: 0.9rem;
  color: var(--ink-soft);
}
.countdown time {
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  color: var(--ink);
  background: var(--surface);
  padding: 0.3rem 0.55rem;
  border-radius: 6px;
  margin-left: 0.25rem;
}

.deals-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 1.25rem;
}
.deal {
  background: var(--surface);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--line);
}
.deal-feature { grid-row: span 2; }
.deal-feature .deal-art { aspect-ratio: 4/5; }
.deal-art {
  aspect-ratio: 16/10;
  position: relative;
}
.deal-art-1 { background: linear-gradient(160deg, #efe4d4, #c9b89c); }
.deal-art-2 { background: linear-gradient(160deg, #2c3037, #4b525c); }
.deal-art-3 { background: linear-gradient(160deg, #d0d8e0, #6c7a8a); }

.deal-body {
  padding: 1.25rem 1.4rem 1.5rem;
}
.badge {
  display: inline-block;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 600;
  color: var(--ink-soft);
  background: var(--muted);
  padding: 0.3rem 0.55rem;
  border-radius: 999px;
  margin-bottom: 0.75rem;
}
.badge-accent {
