  transition: transform 0.18s ease, box-shadow 0.18s ease;
}
.story:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }
.story-link {
  display: flex;
  flex-direction: column;
  height: 100%;
}
.story-link:hover { text-decoration: none; }
.story-art {
  aspect-ratio: 16/10;
}
.story-art-1 { background: linear-gradient(160deg, #b08a64, #6f4f33); }
.story-art-2 { background: linear-gradient(160deg, #c8d3c5, #6f8b75); }
.story-art-3 { background: linear-gradient(160deg, #f0c987, #c46d3d); }
