.story-lead .story-art { aspect-ratio: 16/10; height: auto; }
.story-lead h3 { font-size: 1.6rem; }
.story-lead .story-body { padding: 1.5rem 1.75rem 1.75rem; }

/* Newsletter */
.newsletter {
  padding-block: clamp(3rem, 6vw, 5rem);
