    { id: 'p2', name: 'Carafe No. 3', cat: 'Kitchen', price: 42, was: 58, badge: 'Sale', badgeKind: 'sale', tone: 'linear-gradient(160deg,#eef0e8,#b9c2a8)' },
    { id: 'p3', name: 'Roaming Tote', cat: 'Accessories', price: 124, was: null, badge: null, tone: 'linear-gradient(160deg,#2c3037,#4b525c)' },
    { id: 'p4', name: 'Linen Shirt', cat: 'Apparel', price: 96, was: null, badge: 'Restocked', tone: 'linear-gradient(160deg,#f4e6d2,#d8b888)' },
    { id: 'p5', name: 'Cast Iron Skillet', cat: 'Kitchen', price: 89, was: 110, badge: 'Sale', badgeKind: 'sale', tone: 'linear-gradient(160deg,#3a3d44,#15171a)' },
    { id: 'p6', name: 'Throw Blanket', cat: 'Home', price: 138, was: null, badge: null, tone: 'linear-gradient(160deg,#e8c8d2,#a86f80)' },
    { id: 'p7', name: 'Walking Boot', cat: 'Outdoor', price: 215, was: null, badge: 'New', tone: 'linear-gradient(160deg,#b08a64,#5e4329)' },
    { id: 'p8', name: 'Ceramic Mug Set', cat: 'Kitchen', price: 48, was: 64, badge: 'Sale', badgeKind: 'sale', tone: 'linear-gradient(160deg,#c4ccd6,#5b6776)' }
  ];

  const grid = document.getElementById('productGrid');
  const liveRegion = document.getElementById('liveRegion');
  const cartCountEl = document.getElementById('cartCount');
  const cartBtn = document.getElementById('cartBtn');
  let cartCount = 0;

  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[c]));
  }

  function priceHtml(p) {
    if (p.was) return `<s aria-label="Original price $${p.was}">$${p.was}</s><span aria-label="Sale price $${p.price}">$${p.price}</span>`;
    return `<span aria-label="Price $${p.price}">$${p.price}</span>`;
  }

  function renderProducts() {
    if (!grid) return;
    grid.innerHTML = products.map(p => {
      const badge = p.badge
        ? `<span class="product-badge ${p.badgeKind || ''}">${escapeHtml(p.badge)}</span>`
        : '';
      return `
        <li class="product">
          <div class="product-media" style="background:${p.tone}">
            ${badge}
          </div>
          <div class="product-body">
            <p class="product-cat">${escapeHtml(p.cat)}</p>
            <h3 class="product-name"><a href="#" aria-label="View ${escapeHtml(p.name)}">${escapeHtml(p.name)}</a></h3>
            <div class="product-meta">
              <p class="product-price">${priceHtml(p)}</p>
              <button type="button" class="add-btn" data-id="${p.id}" aria-label="Add ${escapeHtml(p.name)} to cart">Add</button>
            </div>
          </div>
        </li>`;
    }).join('');
  }

  function updateCart(name) {
    cartCount += 1;
    cartCountEl.textContent = String(cartCount);
    cartBtn.setAttribute('aria-label', `Cart, ${cartCount} item${cartCount === 1 ? '' : 's'}`);
    liveRegion.textContent = `${name} added to cart. Cart now has ${cartCount} item${cartCount === 1 ? '' : 's'}.`;
  }

  if (grid) {
    grid.addEventListener('click', (e) => {
      const btn = e.target.closest('.add-btn');
      if (!btn) return;
      const id = btn.getAttribute('data-id');
      const p = products.find(x => x.id === id);
      if (!p) return;
      btn.classList.add('added');
      const original = btn.textContent;
      btn.textContent = 'Added ✓';
      updateCart(p.name);
      setTimeout(() => {
        btn.classList.remove('added');
        btn.textContent = original;
      }, 1400);
    });
  }

  // Countdown timer for deals (resets every 24h)
  const countdownEl = document.getElementById('countdown');
  function tick() {
    if (!countdownEl) return;
    const now = new Date();
    const end = new Date(now);
    end.setHours(24, 0, 0, 0);
    const diff = Math.max(0, end - now);
    const h = String(Math.floor(diff / 3600000)).padStart(2, '0');
    const m = String(Math.floor((diff % 3600000) / 60000)).padStart(2, '0');
    const s = String(Math.floor((diff % 60000) / 1000)).padStart(2, '0');
    countdownEl.textContent = `${h}:${m}:${s}`;
    countdownEl.setAttribute('datetime', `PT${h}H${m}M${s}S`);
  }
  tick();
  setInterval(tick, 1000);

  // Newsletter
  const form = document.getElementById('newsletterForm');
  const status = document.getElementById('formStatus');
  if (form) {
    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const email = form.email.value.trim();
      const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
      status.classList.remove('error', 'success');
      if (!valid) {
        status.classList.add('error');
        status.textContent = 'Please enter a valid email address.';
        form.email.setAttribute('aria-invalid', 'true');
        form.email.focus();
        return;
      }
      form.email.removeAttribute('aria-invalid');
      status.classList.add('success');
      status.textContent = `Thanks! We've added ${email} to the list.`;
      form.reset();
    });
  }

  // Year
  const yearEl = document.getElementById('year');
  if (yearEl) yearEl.textContent = new Date().getFullYear();

  renderProducts();
})();
